package restudio.reglassneo.client.integration;

import net.caffeinemc.mods.sodium.api.config.ConfigEntryPoint;import net.caffeinemc.mods.sodium.api.config.structure.ConfigBuilder;import net.caffeinemc.mods.sodium.api.config.structure.OptionGroupBuilder;import net.caffeinemc.mods.sodium.api.config.structure.OptionPageBuilder;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.neoforged.fml.ModList;import restudio.reglassneo.ReGlass;import restudio.reglassneo.client.api.ReGlassConfig;import restudio.reglassneo.client.config.ReGlassSettingsIO;
public final class ReGlassSodiumConfigEntryPoint implements ConfigEntryPoint {public void registerConfigLate(ConfigBuilder b){if(!ModList.get().isLoaded("reeses_sodium_options"))return;ReGlass.LOGGER.info("ReGlassNeo detected Reese's Sodium Options");b.registerOwnModOptions().addPage(createPage(b));}private OptionPageBuilder createPage(ConfigBuilder b){return b.createOptionPage().setName(Component.literal("Liquid Glass Neo")).addOptionGroup(createAppearance(b)).addOptionGroup(createShadow(b));}private OptionGroupBuilder createAppearance(ConfigBuilder b){ReGlassConfig c=ReGlassConfig.INSTANCE;return b.createOptionGroup().setName(Component.literal("Appearance")).addOption(b.createIntegerOption(id("blur_radius")).setStorageHandler(ReGlassSettingsIO::saveFromMemory).setName(Component.literal("Blur Radius")).setTooltip(Component.literal("SDF glass radius")).setDefaultValue(c.defaultBlurRadius).setRange(0,32,1).setValueFormatter(v->Component.literal(String.valueOf(v))).setBinding(v->{c.defaultBlurRadius=v;},()->c.defaultBlurRadius)).addOption(b.createIntegerOption(id("tint_alpha")).setStorageHandler(ReGlassSettingsIO::saveFromMemory).setName(Component.literal("Tint Alpha")).setTooltip(Component.literal("Glass tint opacity, percent")).setDefaultValue(Math.round(c.defaultTintAlpha*100f)).setRange(0,100,1).setValueFormatter(v->Component.literal(v+"%")).setBinding(v->{c.defaultTintAlpha=v/100f;},()->Math.round(c.defaultTintAlpha*100f)));}private OptionGroupBuilder createShadow(ConfigBuilder b){ReGlassConfig c=ReGlassConfig.INSTANCE;return b.createOptionGroup().setName(Component.literal("Shadow")).addOption(b.createIntegerOption(id("shadow_factor")).setStorageHandler(ReGlassSettingsIO::saveFromMemory).setName(Component.literal("Shadow Factor")).setTooltip(Component.literal("SDF shadow opacity, percent")).setDefaultValue(Math.round(c.defaultShadowFactor*100f)).setRange(0,100,1).setValueFormatter(v->Component.literal(v+"%")).setBinding(v->{c.defaultShadowFactor=v/100f;},()->Math.round(c.defaultShadowFactor*100f))).addOption(b.createIntegerOption(id("shadow_expand")).setStorageHandler(ReGlassSettingsIO::saveFromMemory).setName(Component.literal("Shadow Expand")).setTooltip(Component.literal("SDF shadow spread")).setDefaultValue(Math.round(c.defaultShadowExpand)).setRange(0,100,1).setValueFormatter(v->Component.literal(String.valueOf(v))).setBinding(v->{c.defaultShadowExpand=v;},()->Math.round(c.defaultShadowExpand)));}private static ResourceLocation id(String p){return ResourceLocation.fromNamespaceAndPath("reglassneo",p);}}
